true_values = [380.63, 374.06, 382.45, 376.73];
errors = true_values - f_predict;

% 显示结果
fprintf('预测值\t\t实际值\t\t误差\n');
for i = 1:length(true_values)
fprintf('%.4f\t\t%.4f\t\t%.4f\n', f_predict(i), true_values(i), errors(i));
end


